import {properties,neighborhoods,filterProperties,state,money} from './data.js';
import {header,footer,button,photo,icon,card,regionOptions,empty,escapeHTML} from './ui.js';
export function home(){return `${header()}<main id="main"><section class="home-hero"><div class="hero-geometry"><i></i><i></i><i></i></div>${photo('hero','hero-building')}<div class="hero-copy"><span class="eyebrow">NOVOS JEITOS DE MORAR. NOVOS COMEÇOS.</span><h1>Encontre um lugar<br>para chamar de seu<br>na <span class="underline">Zona Leste.</span></h1><p>Imóveis selecionados, um olhar para a região<br>e uma nova forma de descobrir possibilidades.</p></div><form class="hero-search glass" id="home-search"><label>${icon('search')}<input name="query" aria-label="Buscar por bairro ou código" placeholder="Buscar por bairro ou código do imóvel"></label><label class="region-select">${icon('pin')}<select name="region" aria-label="Região">${regionOptions()}</select></label><button class="btn dark">Buscar imóveis${icon('arrow')}</button></form><div class="hero-caption">01 / 03 <span>ARQUITETURA PARA VIVER A CIDADE</span></div></section><section class="value-strip">${[['pin','Foco na Zona Leste','Um olhar atento aos bairros<br>e às suas possibilidades.'],['layers','Mais que um anúncio','Espaços, contexto e informação<br>para uma escolha consciente.'],['heart','Property Match','Descubra imóveis que<br>combinam com o seu momento.'],['calendar','Do interesse à visita','Uma experiência simples,<br>do primeiro olhar ao encontro.']].map(([i,t,d])=>`<div>${icon(i)}<h3>${t}</h3><p>${d}</p></div>`).join('')}</section><section class="section neighborhoods"><div class="section-heading"><div><span class="eyebrow">EXPLORE A REGIÃO</span><h2>Vários bairros.<br>Um lugar para você.</h2></div><a class="text-link" href="#/busca">Explorar a Zona Leste${icon('arrow')}</a></div><div class="neighborhood-grid">${neighborhoods.slice(0,4).map((n,i)=>`<a href="#/busca?region=${encodeURIComponent(n)}" class="neighborhood">${photo(['facade','district2','district3','district4'][i])}<span>${n}${icon('arrow')}</span></a>`).join('')}</div><p class="micro">Imagens de atmosfera ilustrativas; não representam os bairros indicados.</p></section><section class="match-promo"><div><span class="eyebrow">PROPERTY MATCH</span><h2>Seu próximo lar.<br>Do seu jeito.</h2><p>Conte o que importa para você.<br>Curta, descubra e encontre novas possibilidades.</p>${button('Experimentar o Match','#/match')}</div><div class="promo-phone-wrap"><div class="bauhaus-composition"><i></i><i></i><i></i></div><div class="mini-phone"><div class="phone-speaker"></div><strong>Property Match<span>♥</span></strong>${photo('living')}<div class="mini-caption"><small>APARTAMENTO NA PENHA</small><b>R$ 2.800 <small>/mês</small></b></div><div class="mini-actions"><span>×</span><span>♡</span></div></div></div><div class="promo-steps"><div>${icon('filter')}Suas preferências<span>01</span></div><div>${icon('heart')}Uma conexão com seu espaço<span>02</span></div><div>${icon('calendar')}Seu próximo encontro<span>03</span></div><p>Compatibilidade simulada.<br>Uma demonstração de novas possibilidades.</p></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">NOSSA SELEÇÃO</span><h2>Espaços que inspiram.</h2></div><a href="#/busca" class="text-link">Ver todos os imóveis${icon('arrow')}</a></div><div class="property-grid">${properties.slice(0,4).map(p=>card(p)).join('')}</div></section><section class="editorial-banner">${photo('balcony')}<div><span class="eyebrow">UM NOVO OLHAR PARA MORAR</span><h2>São Paulo é imensa.<br>Seu lugar é único.</h2><p>Arquitetura, mobilidade e os pequenos detalhes<br>que fazem a vida acontecer.</p>${button('Conheça a seleção Signature','#/signature/AP-11869','light')}</div><span class="editorial-number">ZL / 23°S</span></section><div class="demo-ribbon">${icon('info')}Este é um protótipo visual. Todos os imóveis, valores e avaliações são fictícios.</div></main>${footer()}`;}
export function mapMarkup(items,selected=items[0]?.id){return `<div class="map-canvas" aria-label="Mapa vetorial ilustrativo da Zona Leste"><svg class="street-map" viewBox="0 0 600 700" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="blocks" width="64" height="48" patternTransform="rotate(-24)" patternUnits="userSpaceOnUse"><rect width="64" height="48" fill="#e8e2d7"/><path d="M0 0H64V48H0Z" fill="none" stroke="#faf7f0" stroke-width="3"/><path d="M32 0V48" stroke="#faf7f0" stroke-width="1"/></pattern></defs><rect width="600" height="700" fill="url(#blocks)"/><path d="m0 80 120 30 30-60 70-30 70 20-30 70-100 60-100-20Z M420 520l100-100 80 40v180l-110-20Z M0 590l100-30 40 140H0" fill="#c5cfae"/><path d="M-20 190Q160 400 300 230T640 90M-20 570Q180 370 360 560T640 520" fill="none" stroke="#faf8f1" stroke-width="17"/><path d="M-20 190Q160 400 300 230T640 90M-20 570Q180 370 360 560T640 520" fill="none" stroke="#d4c6ac" stroke-width="3"/><path d="M480-20Q270 140 480 360T390 740" fill="none" stroke="#f9f8f0" stroke-width="13"/><path d="M480-20Q270 140 480 360T390 740" fill="none" stroke="#9dbfc4" stroke-width="6"/></svg><span class="map-label penha">PENHA</span><span class="map-label matilde">VILA MATILDE</span><span class="map-label tatuape">TATUAPÉ</span><span class="map-label formosa">VILA FORMOSA</span>${items.map(p=>`<button class="map-marker ${p.id===selected?'selected':''}" style="left:${p.position[0]}%;top:${p.position[1]}%" data-map-property="${p.id}" aria-label="Selecionar ${p.name}">${money(p.price)}</button>`).join('')}<div class="map-key">${icon('pin')} Mapa ilustrativo · posições fictícias</div><div class="map-preview" id="map-preview">${items.find(p=>p.id===selected)?card(items.find(p=>p.id===selected),true):''}</div></div>`;}
export function search(params=new URLSearchParams()){const filters={mode:params.get('mode')||'Alugar',region:params.get('region')||'',query:params.get('query')||'',max:params.get('max')||'',beds:params.get('beds')||'',parking:params.get('parking')||'',quiet:params.get('quiet')==='on'};const items=filterProperties(properties,filters);return `${header('busca')}<main id="main"><section class="search-hero"><div><span class="eyebrow">UM NOVO OLHAR PARA A ZONA LESTE</span><h1>Encontre seu imóvel.<br><span class="underline">Encontre seu lugar.</span></h1><p>Explore, compare e descubra novas possibilidades.</p></div>${photo('hero')}<div class="search-arc"></div></section><div class="search-workspace"><aside class="filter-panel"><h2>${icon('filter')}Filtros</h2><form id="filters"><label>Modalidade<select name="mode"><option ${filters.mode==='Alugar'?'selected':''}>Alugar</option><option ${filters.mode==='Comprar'?'selected':''}>Comprar</option></select></label><label>Buscar por nome ou código<input name="query" value="${escapeHTML(filters.query)}" placeholder="Ex.: AP-11876"></label><label>Bairro<select name="region">${regionOptions(filters.region)}</select></label><label>Valor máximo<input name="max" type="number" min="0" step="50" value="${escapeHTML(filters.max)}" placeholder="Sem limite"></label><div class="form-row"><label>Dormitórios<select name="beds"><option value="">Todos</option>${[1,2,3].map(n=>`<option value="${n}" ${filters.beds==n?'selected':''}>${n} ou mais</option>`).join('')}</select></label><label>Vagas<select name="parking"><option value="">Todas</option>${[1,2].map(n=>`<option value="${n}" ${filters.parking==n?'selected':''}>${n} ou mais</option>`).join('')}</select></label></div><details open><summary>Preferências da região</summary><label class="check-label"><input name="quiet" type="checkbox" ${filters.quiet?'checked':''}>Ruído percebido baixo</label><p class="micro">Avaliações fictícias registradas pelo corretor, com contexto e origem.</p></details><button class="btn dark full">${icon('search')}Aplicar filtros</button><a class="clear-filter" href="#/busca">Limpar filtros</a></form></aside><section class="results"><div class="results-heading"><div><h2>${items.length} ${items.length===1?'imóvel encontrado':'imóveis encontrados'}</h2><span>Seleção demonstrativa · Zona Leste</span></div><div class="view-toggle"><button class="selected" data-view="split" aria-label="Lista e mapa">${icon('layers')}</button><button data-view="list" aria-label="Somente lista">${icon('menu')}</button><button data-view="map" aria-label="Somente mapa">${icon('pin')}</button></div></div><div class="results-body"><div class="results-list">${items.length?items.map(p=>card(p,true)).join(''):empty('Nenhum imóvel por aqui','Experimente ampliar o valor ou escolher outro bairro.','#/busca','Limpar filtros')}</div><div class="search-map">${mapMarkup(items)}</div></div></section></div><div class="demo-ribbon">${icon('info')}Catálogo e mapa demonstrativos. As posições não indicam endereços reais.</div></main>${footer()}`;}
export function favorites(){const items=properties.filter(p=>state.favorites.includes(p.id));return `${header()}<main id="main" class="section favorites-page"><span class="eyebrow">SUA SELEÇÃO</span><h1>Lugares para guardar.</h1><p>Seus imóveis favoritos, reunidos para comparar com calma.</p><div class="property-grid">${items.map(p=>card(p)).join('')}</div>${items.length?'':empty('Sua seleção começa aqui','Toque no coração de um imóvel para salvá-lo.')}<div class="demo-ribbon">Favoritos salvos apenas neste navegador.</div></main>${footer()}`;}
